describe("operational status", () => {
  it("reports liveness independently from configuration readiness", () => {
    expect(healthStatus()).toEqual({
      service: "driftlens",
      status: "ok",
    });
  });

  it("reports ready for valid production configuration", () => {
    expect(
      readinessStatus(
