    private readonly clock: Clock = () => new Date().toISOString(),
    private readonly idFactory: IdFactory = randomUUID,
  ) {}

  source(): SourceMetadata {
    return this.sourceMetadata;
  }

  start(requestedRef: string): ScanRecord {
    if (this.activeScanId !== null) {
      throw new ScanExecutionError("SCAN_ACTIVE");
    }

    const id = this.idFactory();
    this.activeScanId = id;
    try {
      return this.repository.createQueued(id, requestedRef, this.clock());
    } catch (error) {
      this.activeScanId = null;
      throw error;
    }
  }

  async run(id: string): Promise<void> {
    if (this.activeScanId !== id) {
      return;
    }

    try {
      this.repository.transition(
        id,
        "LOADING_DESIRED",
        "RUNNING",
        this.clock(),
      );
      const queued = this.repository.get(id);
      if (!queued) {
        throw new ScanExecutionError("SCAN_NOT_FOUND");
      }

      const desiredSource = await this.desiredState.load(queued.requestedRef);
      const desired = parseDesiredDeployment(desiredSource.yaml);
      this.repository.saveDesired(
        id,
        desiredSource.resolvedSha,
        desired.target,
        desired.projection,
        this.clock(),
      );

      const live = await this.liveState.read(desired.target);
      this.repository.saveLive(id, live, this.clock());
      const result = compareDeployments(desired.projection, live);

      this.repository.transition(id, "SAVING_RESULT", "RUNNING", this.clock());
      this.repository.complete(id, result, this.clock());
    } catch (error) {
      const safeError = safeScanError(error);
      try {
        this.repository.fail(id, safeError, this.clock());
      } catch {
        this.recordVolatileStorageFailure(id);
      }
    } finally {
      this.activeScanId = null;
    }
  }

  get(id: string): ScanRecord | null {
    return this.volatileFailures.get(id) ?? this.repository.get(id);
  }

  list(limit: number): ScanRecord[] {
    const durable = this.repository.list(limit);
    return durable.map(
      (record) => this.volatileFailures.get(record.id) ?? record,
    );
  }

  private recordVolatileStorageFailure(id: string): void {
    let record: ScanRecord | null = null;
    try {
      record = this.repository.get(id);
    } catch {
      // The API will surface repository unavailability if reads also fail.
    }
    if (!record) {
      return;
    }

    const at = this.clock();
    this.volatileFailures.set(id, {
      ...record,
      completedAt: at,
      durable: false,
      error: new ScanExecutionError("STORAGE_WRITE_FAILED").toSafeError(),
      stage: "FAILED",
      status: "FAILED",
      updatedAt: at,
    });
    if (this.volatileFailures.size > 50) {
      const oldest = this.volatileFailures.keys().next().value as
        string | undefined;
      if (oldest) {
        this.volatileFailures.delete(oldest);
      }
    }
  }
}
import { mkdirSync } from "node:fs";
import { join } from "node:path";

import { resolveRuntimeConfiguration } from "@/server/runtime-config";
import { ScanExecutionError } from "@/server/scans/errors";
import { GitHubDesiredStateReader } from "@/server/scans/github";
import {
  createAppsV1Client,
  KubernetesDeploymentReader,
} from "@/server/scans/kubernetes";
import { SqliteScanRepository } from "@/server/scans/repository";
import { ScanService } from "@/server/scans/service";

declare global {
  var __driftlensScanService: ScanService | undefined;
}

export function getScanService(): ScanService {
  if (globalThis.__driftlensScanService) {
    return globalThis.__driftlensScanService;
  }

  const configuration = resolveRuntimeConfiguration();
  if (!configuration.ready) {
    throw new ScanExecutionError("CONFIGURATION_INVALID");
  }

  try {
    mkdirSync(configuration.dataDirectory, { recursive: true });
    const repository = new SqliteScanRepository(
      join(configuration.dataDirectory, "driftlens.sqlite"),
    );
    const desiredState = new GitHubDesiredStateReader(
      configuration.scan.repository,
      configuration.scan.manifestPath,
    );
    const liveState = new KubernetesDeploymentReader(
      createAppsV1Client(
        configuration.scan.kubeconfigPath,
        configuration.scan.kubeContext,
      ),
    );
    globalThis.__driftlensScanService = new ScanService(
      repository,
      desiredState,
      liveState,
      {
        manifestPath: configuration.scan.manifestPath,
        repository: configuration.scan.repository,
      },
    );
    return globalThis.__driftlensScanService;
  } catch (error) {
    if (error instanceof ScanExecutionError) {
      throw error;
    }
    throw new ScanExecutionError("CONFIGURATION_INVALID", { cause: error });
  }
}

