  "api": "import type { ScanRecord } from "@/server/scans/contracts";
import { historyLimitSchema, startScanSchema } from "@/server/scans/contracts";
import { ScanExecutionError } from "@/server/scans/errors";
import type { ScanService } from "@/server/scans/service";

type Scheduler = (task: () => Promise<void>) => void;
const MAX_REQUEST_BYTES = 1_024;

function json(body: unknown, status = 200): Response {
  return Response.json(body, { status });
}

export function scanErrorResponse(error: unknown): Response {
  if (!(error instanceof ScanExecutionError)) {
    return json(
      { error: new ScanExecutionError("INTERNAL_ERROR").toSafeError() },
      500,
    );
  }

  const status =
    error.code === "SCAN_ACTIVE"
      ? 409
      : error.code === "SCAN_NOT_FOUND"
        ? 404
        : error.code.startsWith("STORAGE_")
          ? 503
          : error.code === "CONFIGURATION_INVALID"
            ? 503
            : 500;
  return json({ error: error.toSafeError() }, status);
}

function scanEnvelope(scan: ScanRecord): { scan: ScanRecord } {
  return { scan };
}

async function readBoundedBody(request: Request): Promise<string | null> {
  const declaredLength = request.headers.get("content-length");
  if (
    declaredLength !== null &&
    Number.isFinite(Number(declaredLength)) &&
    Number(declaredLength) > MAX_REQUEST_BYTES
  ) {
    return null;
  }
  if (request.body === null) {
    return "";
  }

  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let totalBytes = 0;
  let text = "";
  while (true) {
    const chunk = await reader.read();
    if (chunk.done) {
      return text + decoder.decode();
    }
    totalBytes += chunk.value.byteLength;
    if (totalBytes > MAX_REQUEST_BYTES) {
      await reader.cancel();
      return null;
    }
    text += decoder.decode(chunk.value, { stream: true });
  }
}

export async function startScanResponse(
  request: Request,
  service: ScanService,
  schedule: Scheduler,
): Promise<Response> {
  try {
    const text = await readBoundedBody(request);
    if (text === null) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }
    const parsed = startScanSchema.safeParse(JSON.parse(text));
    if (!parsed.success) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }

    const scan = service.start(parsed.data.ref);
    schedule(() => service.run(scan.id));
    return json(scanEnvelope(scan), 202);
  } catch (error) {
    if (error instanceof SyntaxError) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }
    return scanErrorResponse(error);
  }
}

export function listScansResponse(
  request: Request,
  service: ScanService,
): Response {
  try {
    const rawLimit = new URL(request.url).searchParams.get("limit") ?? "20";
    const limit = historyLimitSchema.safeParse(rawLimit);
    if (!limit.success) {
      return json(
        { error: { code: "INVALID_LIMIT", message: "Limit is invalid." } },
        400,
      );
    }
    return json({ scans: service.list(limit.data) });
  } catch (error) {
    return scanErrorResponse(error);
  }
}

export function getScanResponse(id: string, service: ScanService): Response {
  try {
    const scan = service.get(id);
    if (!scan) {
      throw new ScanExecutionError("SCAN_NOT_FOUND");
    }
    return json(scanEnvelope(scan));
  } catch (error) {
    return scanErrorResponse(error);
  }
}

export function sourceResponse(service: ScanService): Response {
  return json({ source: service.source() });
}
",
  "deployment": "import { parseAllDocuments } from "yaml";
import { z } from "zod";

import type {
  ComparisonResult,
  DeploymentProjection,
  DeploymentTarget,
  Difference,
} from "@/server/scans/contracts";
import { ScanExecutionError } from "@/server/scans/errors";

const dnsSubdomain = z
  .string()
  .min(1)
  .max(253)
  .regex(/^[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?$/)
  .refine((value) => value.split(".").every((label) => label.length <= 63));
const dnsLabel = z
  .string()
  .min(1)
  .max(63)
  .regex(/^[a-z0-9](?:[-a-z0-9]*[a-z0-9])?$/);
const containerSchema = z.object({
  image: z.string().trim().min(1).max(2_048),
  name: dnsLabel,
});
const deploymentSchema = z.object({
  apiVersion: z.string(),
  kind: z.string(),
  metadata: z.object({
    name: dnsSubdomain,
    namespace: dnsLabel,
  }),
  spec: z.object({
    replicas: z.number().int().min(0).optional(),
    template: z.object({
      spec: z.object({
        containers: z.array(containerSchema).min(1),
      }),
    }),
  }),
});

export interface DesiredDeployment {
  projection: DeploymentProjection;
  target: DeploymentTarget;
}

export function parseDesiredDeployment(yaml: string): DesiredDeployment {
  let documents;
  try {
    documents = parseAllDocuments(yaml);
  } catch (error) {
    throw new ScanExecutionError("MANIFEST_INVALID", { cause: error });
  }

  if (
    documents.length !== 1 ||
    documents[0]?.errors.length !== 0 ||
    documents[0].contents === null
  ) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  const result = deploymentSchema.safeParse(documents[0].toJS());
  if (!result.success) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  if (
    result.data.apiVersion !== "apps/v1" ||
    result.data.kind !== "Deployment"
  ) {
    throw new ScanExecutionError("MANIFEST_UNSUPPORTED");
  }

  const containerNames = result.data.spec.template.spec.containers.map(
    ({ name }) => name,
  );
  if (new Set(containerNames).size !== containerNames.length) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  return {
    projection: {
      containers: result.data.spec.template.spec.containers
        .map(({ image, name }) => ({ image, name }))
        .sort((left, right) => left.name.localeCompare(right.name)),
      replicas: result.data.spec.replicas ?? 1,
    },
    target: {
      apiVersion: "apps/v1",
      kind: "Deployment",
      name: result.data.metadata.name,
      namespace: result.data.metadata.namespace,
    },
  };
}

export function compareDeployments(
  desired: DeploymentProjection,
  live: DeploymentProjection | null,
): ComparisonResult {
  if (live === null) {
    return { differences: [], outcome: "MISSING_LIVE" };
  }

  const differences: Difference[] = [];
  if (desired.replicas !== live.replicas) {
    differences.push({
      desired: desired.replicas,
      field: "spec.replicas",
      live: live.replicas,
    });
  }

  const liveContainers = new Map(
    live.containers.map((container) => [container.name, container.image]),
  );
  for (const container of desired.containers) {
    const liveImage = liveContainers.get(container.name) ?? null;
    if (container.image !== liveImage) {
      differences.push({
        desired: container.image,
        field: `spec.template.spec.containers[name=${container.name}].image`,
        live: liveImage,
      });
    }
  }

  return {
    differences,
    outcome: differences.length === 0 ? "IN_SYNC" : "DRIFTED",
  };
}
