    ["invalid manifest", null, "not: [valid", null, "MANIFEST_INVALID"],
    [
      "Kubernetes denial",
      null,
      MANIFEST,
      new ScanExecutionError("KUBERNETES_FORBIDDEN"),
      "KUBERNETES_FORBIDDEN",
